\begin{ex}%[9D3H4-2]
Xét tính đúng-sai của các khẳng định sau:
\choiceTF
{ \True $\sqrt[3]{y} = a$ suy ra $y = a^3$ }
   { \True $20-\sqrt[3]{216}=14$ }
     { \True $\sqrt[3]{-2,5}.\sqrt[3]{0,25}.\sqrt[3]{\dfrac{-16}{10 x^{3}}}$=$1.\dfrac{1}{x}$ }
    { Biết ${x}$ thỏa mãn $\left( 4\sqrt[3]{x - 1} \right). \left( -3\sqrt[3]{x + 1}\right)= -12$. Khi đó $x^2={4}$ }
\loigiai{
a) Khẳng định đã cho là khẳng định đúng.\\
$\sqrt[3]{y} = a$ suy ra $y = a^3$.\\
b) Khẳng định đã cho là khẳng định đúng.\\
$20-\sqrt[3]{216}=14$\\
c) Khẳng định đã cho là khẳng định đúng.\\
$\sqrt[3]{-2,5} .\sqrt[3]{0,25}.\sqrt[3]{\dfrac{-16}{10 x^{3}}}= 1.\dfrac{1}{x}$\\
d) Khẳng định đã cho là khẳng định sai.\\
$\left( 4\sqrt[3]{x - 1} \right) \cdot \left( -3\sqrt[3]{x + 1} \right) = -12$\\
$\sqrt[3]{x^{2} - 1} = 1$\\
$x^{2} = 2$
}\end{ex}

